-- ==============================================================================
-- Autonomous Software Development Team - Database Schema
-- Database: PostgreSQL
-- Description: Stores project specs, agent deliverables, and conversation memory
-- ==============================================================================

-- 1. Projects Table
-- Stores the lifecycle stages and deliverables generated by the agent team.
CREATE TABLE IF NOT EXISTS projects (
    id SERIAL PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    raw_idea TEXT NOT NULL,
    status VARCHAR(50) NOT NULL DEFAULT 'SPEC_DRAFT',
    spec_data JSONB,
    architecture_plan JSONB,
    qa_report JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index for status filtering and fast lookup
CREATE INDEX IF NOT EXISTS idx_projects_status ON projects (status);
CREATE INDEX IF NOT EXISTS idx_projects_created_at ON projects (created_at DESC);

-- Trigger to automatically update updated_at timestamp
CREATE OR REPLACE FUNCTION update_projects_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_projects_updated_at ON projects;
CREATE TRIGGER trg_projects_updated_at
    BEFORE UPDATE ON projects
    FOR EACH ROW
    EXECUTE FUNCTION update_projects_updated_at();

-- 2. Chat Memory Table (LangChain Postgres Chat Memory)
-- Used by the ADMIN Agent in n8n for multi-turn contextual reasoning.
CREATE TABLE IF NOT EXISTS n8n_chat_ADMIN_historial (
    id SERIAL PRIMARY KEY,
    session_id VARCHAR(255) NOT NULL,
    message JSONB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index for rapid session lookup during workflow execution
CREATE INDEX IF NOT EXISTS idx_n8n_chat_admin_session_id ON n8n_chat_ADMIN_historial (session_id);
